import { decodeImaWav } from "./containers/wav-ima.js";
import { createHash } from "node:crypto";
import assert from "node:assert/strict";
import { it } from "node:test";
import { parseWav, wavAst, probeWavSource } from "./containers/adapters.js";

// Native FFmpeg IMA WAV encoding of nine PCM16 samples, padded to a full block.
const input = Buffer.from("", "hex");


it("decodes an IMA WAV block including its predictor and padded samples", () => {
  const doc = parseWav(input);
  const audio = doc.tracks[0]!.decodedAudio!;
  assert.equal(doc.duration, 2041);
  const pcm = Buffer.alloc(2041 * 2);
  audio.channelData[0]!.forEach((n, i) => pcm.writeInt16LE(n * 32768, i * 2));
  assert.equal(createHash("sha256").update(pcm).digest("hex"), "383ba5eb8798cd090edb3bfa9968d26dd38f76f343fab0de202ef7325108dc7e");
});

it("probes IMA WAV codec, duration and block packets without decoding", async () => {
  const buffered = await wavAst().probe!(input, { showPackets: true });
  const ranged = await probeWavSource({ size: input.length, async read(offset, length) { return input.subarray(offset, offset + length); } }, { showPackets: true });
  for (const probe of [buffered, ranged]) {
    assert.equal(probe.streams[0]!.codec_name, "adpcm_ima_wav");
    assert.equal(probe.streams[0]!.duration, "0.256000");
    const packets = Array.from(probe.packets!);
    assert.equal(packets.length, 1);
    assert.equal(packets[0]!.duration, 2041);
    assert.equal(packets[0]!.size, "1024");
  }
});

for (const index of [89, 256, 344, 32768, 65535]) {
  it(`rejects invalid IMA step index ${index} instead of fabricating audio`, () => {
    const invalid = Buffer.from(input);
    invalid.writeUInt16LE(index, invalid.indexOf("data") + 10);
    assert.throws(() => parseWav(invalid), /IMA.*index/);
  });
}

for (const channels of [1, 2]) for (let badChannel = 0; badChannel < channels; badChannel++) {
  for (const badBlock of [0, 1, 2]) it(`skips IMA block ${badBlock} with an invalid index in channel ${badChannel} of ${channels}`, () => {
    const blockAlign = channels * 8;
    const data = new Uint8Array(blockAlign * 3);
    const view = new DataView(data.buffer);
    for (let block = 0; block < 3; block++) for (let ch = 0; ch < channels; ch++) {
      view.setInt16(block * blockAlign + ch * 4, (block + 1) * 1000 * (ch ? -1 : 1), true);
    }
    data[badBlock * blockAlign + badChannel * 4 + 2] = 100;
    const decoded = decodeImaWav(data, channels, blockAlign, 27);
    for (let ch = 0; ch < channels; ch++) {
      assert.deepEqual(Array.from(decoded[ch]!, sample => sample * 32768),
        [0, 1, 2].filter(block => block !== badBlock).flatMap(block => Array(9).fill((block + 1) * 1000 * (ch ? -1 : 1))));
    }
  });
}
